sourcesContent:
import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';

import './Prediction.css';
import backgroundImage from '../assets/background.jpg';
import sunIcon from '../assets/sun.png';
import moonIcon from '../assets/moon.png';
import sendIcon from '../assets/send.png';

const translations = {
  en: {
    languageLabel: 'Language:',
    yes: 'yes',
    no: 'no',
    startOver: 'Start Over',
    home: '🏠 Home',
    visualization: '📊 Visualization',
    darkModeOn: 'Dark Mode',
    darkModeOff: 'Light Mode',
    typing: 'Typing...',
    questions: [
      "How old are you?",
      "What is your gender?",
      "What's your BMI (Body Mass Index)?",
      "What's your HbA1c Level (%)?",
      "What's your Blood Glucose Level (mg/dL)?",
      "Do you have hypertension?",
      "Do you have heart disease?",
      "What is your smoking history?"
    ],
    genderOptions: ['Female', 'Male', 'Other'],
    smokingOptions: ['never', 'former', 'current', 'not current', 'ever'],
    generalAdviceTitle: "🌟 General Tips:",
    generalAdvice: [
      '🩺 Monitor your blood sugar levels regularly.',
      '⚖️ Maintain a healthy weight.',
      '🏃 Stay physically active (at least 150 minutes/week).',
      '📅 Get regular check-ups with your doctor.',
    ],
    dietAdviceTitle: "🍎 Dietary Advice:",
    dietAdvice: [
      '🥦 Eat plenty of non-starchy vegetables.',
      '🌾 Choose whole grains over refined ones.',
      '🥤 Limit sugary drinks and juices.',
      '🥑 Include healthy fats like avocados and nuts.',
    ],
    warningSignsTitle: "⚠️ Watch for these warning signs:",
    warningSigns: [
      '🚽 Frequent urination.',
      '😰 Excessive thirst.',
      '📉 Unexplained weight loss.',
      '😴 Fatigue and blurred vision.',
    ],
    startMessage1: "Hi there! 👋 I'm your Diabetes Risk Assistant.",
    startMessage2: "Let's get started!",
    thankYou: "Thank you for your answers. Calculating your risk...",
    riskResult: (risk) => `Your predicted diabetes risk is: ${risk}%`,
    fallbackRisk: (risk) => `Based on your inputs, your estimated risk is: ${risk}%`,
    adviceQuestion: "Would you like some advice on how to reduce diabetes risk?",
    adviceYesNo: ['yes', 'no'],
    pleaseYesNo: "Please answer 'yes' or 'no'.",
    pleaseChoose: (opts) => `Please choose one of: ${opts.join(', ')}`,
    enterNumberBetween: (min, max) => `Please enter a number between ${min} and ${max}`,
    alrightAdviceDeclined: "Alright, feel free to come back anytime if you need advice.",
    okayMoreAdvice: "Okay, feel free to ask for more advice anytime!",
    allAdviceDone: "That's all the advice for now. Stay healthy! 💙",
    consultDoctor: "Remember to consult with your doctor for personalized advice.",
  },
  fr: {
    languageLabel: 'Langue :',
    yes: 'oui',
    no: 'non',
    startOver: 'Recommencer',
    home: '🏠 Accueil',
    visualization: '📊 Visualisation',
    darkModeOn: 'Mode Sombre',
    darkModeOff: 'Mode Clair',
    typing: 'En train d\'écrire...',
    questions: [
      "Quel âge avez-vous ?",
      "Quel est votre genre ?",
      "Quel est votre IMC (Indice de Masse Corporelle) ?",
      "Quel est votre taux d'HbA1c (%) ?",
      "Quel est votre taux de glucose sanguin (mg/dL) ?",
      "Avez-vous de l'hypertension ?",
      "Avez-vous une maladie cardiaque ?",
      "Quel est votre historique tabagique ?"
    ],
    genderOptions: ['Femme', 'Homme', 'Autre'],
    smokingOptions: ['jamais', 'ancien', 'actuel', 'pas actuel', 'déjà fumé'],
    generalAdviceTitle: "🌟 Conseils généraux :",
    generalAdvice: [
      '🩺 Surveillez régulièrement votre glycémie.',
      '⚖️ Maintenez un poids sain.',
      '🏃 Restez physiquement actif (au moins 150 minutes/semaine).',
      '📅 Faites des contrôles réguliers chez votre médecin.',
    ],
    dietAdviceTitle: "🍎 Conseils diététiques :",
    dietAdvice: [
      '🥦 Mangez beaucoup de légumes non féculents.',
      '🌾 Choisissez des grains entiers plutôt que raffinés.',
      '🥤 Limitez les boissons sucrées et les jus.',
      '🥑 Incluez des graisses saines comme les avocats et les noix.',
    ],
    warningSignsTitle: "⚠️ Surveillez ces signes d'alerte :",
    warningSigns: [
      '🚽 Mictions fréquentes.',
      '😰 Soif excessive.',
      '📉 Perte de poids inexpliquée.',
      '😴 Fatigue et vision floue.',
    ],
    startMessage1: "Bonjour ! 👋 Je suis votre assistant pour le risque de diabète.",
    startMessage2: "Commençons !",
    thankYou: "Merci pour vos réponses. Calcul du risque...",
    riskResult: (risk) => `Votre risque de diabète prédit est : ${risk}%`,
    fallbackRisk: (risk) => `Selon vos données, votre risque estimé est : ${risk}%`,
    adviceQuestion: "Souhaitez-vous des conseils pour réduire le risque de diabète ?",
    adviceYesNo: ['oui', 'non'],
    pleaseYesNo: "Veuillez répondre par 'oui' ou 'non'.",
    pleaseChoose: (opts) => `Veuillez choisir parmi : ${opts.join(', ')}`,
    enterNumberBetween: (min, max) => `Veuillez entrer un nombre entre ${min} et ${max}`,
    alrightAdviceDeclined: "D'accord, revenez quand vous voulez pour des conseils.",
    okayMoreAdvice: "D'accord, n'hésitez pas à demander plus de conseils !",
    allAdviceDone: "Voilà tous les conseils pour le moment. Restez en bonne santé ! 💙",
    consultDoctor: "N'oubliez pas de consulter votre médecin pour des conseils personnalisés.",
  },
  ar: {
    languageLabel: 'اللغة:',
    yes: 'نعم',
    no: 'لا',
    startOver: 'ابدأ من جديد',
    home: '🏠 الصفحة الرئيسية',
    visualization: '📊 التمثيل البياني',
    darkModeOn: 'الوضع الداكن',
    darkModeOff: 'الوضع الفاتح',
    typing: '...يكتب',
    questions: [
      "كم عمرك؟",
      "ما هو جنسك؟",
      "ما هو مؤشر كتلة الجسم (BMI) الخاص بك؟",
      "ما هو مستوى HbA1c (%) الخاص بك؟",
      "ما هو مستوى جلوكوز الدم (mg/dL) الخاص بك؟",
      "هل تعاني من ارتفاع ضغط الدم؟",
      "هل تعاني من أمراض القلب؟",
      "ما هو تاريخ تدخينك؟"
    ],
    genderOptions: ['أنثى', 'ذكر', 'آخر'],
    smokingOptions: ['أبدا', 'سابق', 'حالي', 'ليس حاليا', 'سبق'],
    generalAdviceTitle: "🌟 نصائح عامة:",
    generalAdvice: [
      '🩺 راقب مستويات السكر في الدم بانتظام.',
      '⚖️ حافظ على وزن صحي.',
      '🏃 كن نشيطاً بدنيا (150 دقيقة على الأقل في الأسبوع).',
      '📅 قم بالفحوصات الدورية مع طبيبك.',
    ],
    dietAdviceTitle: "🍎 نصائح غذائية:",
    dietAdvice: [
      '🥦 تناول الكثير من الخضروات غير النشوية.',
      '🌾 اختر الحبوب الكاملة بدلاً من المكررة.',
      '🥤 قلل من المشروبات والعصائر المحلاة.',
      '🥑 أدرج الدهون الصحية مثل الأفوكادو والمكسرات.',
    ],
    warningSignsTitle: "⚠️ راقب علامات التحذير التالية:",
    warningSigns: [
      '🚽 كثرة التبول.',
      '😰 العطش المفرط.',
      '📉 فقدان الوزن غير المبرر.',
      '😴 التعب وتشوش الرؤية.',
    ],
    startMessage1: "مرحباً! 👋 أنا مساعدك في تقييم خطر الإصابة بالسكري.",
    startMessage2: "لنبدأ!",
    thankYou: "شكراً لإجاباتك. جارٍ حساب الخطر...",
    riskResult: (risk) => `مخاطر الإصابة بالسكري المتوقعة لديك هي: ${risk}%`,
    fallbackRisk: (risk) => `بناءً على مدخلاتك، تقدير الخطر هو: ${risk}%`,
    adviceQuestion: "هل ترغب في بعض النصائح لتقليل خطر الإصابة بالسكري؟",
    adviceYesNo: ['نعم', 'لا'],
    pleaseYesNo: "يرجى الإجابة بـ 'نعم' أو 'لا'.",
    pleaseChoose: (opts) => `يرجى اختيار أحد الخيارات: ${opts.join(', ')}`,
    enterNumberBetween: (min, max) => `يرجى إدخال رقم بين ${min} و${max}`,
    alrightAdviceDeclined: "حسناً، لا تتردد في العودة متى أردت للنصائح.",
    okayMoreAdvice: "حسناً، لا تتردد في طلب المزيد من النصائح في أي وقت!",
    allAdviceDone: "هذه هي كل النصائح الآن. حافظ على صحتك! 💙",
    consultDoctor: "تذكر استشارة طبيبك للحصول على نصائح شخصية.",
  }
};

const Prediction = () => {
  const navigate = useNavigate();
  const [lang, setLang] = useState('en');
  const t = translations[lang];

  const [darkMode, setDarkMode] = useState(true);
  const [chat, setChat] = useState([]);
  const [input, setInput] = useState('');
  const [currentStep, setCurrentStep] = useState(-2); // -2: greeting1, -1: greeting2, 0..7 questions, 8: ask advice, 9+: advice flow
  const [isTyping, setIsTyping] = useState(false);

  const [userAnswers, setUserAnswers] = useState({
    age: null,
    gender: '',
    bmi: null,
    hba1c: null,
    glucose: null,
    hypertension: '',
    heartDisease: '',
    smoking: ''
  });

  const [adviceStep, setAdviceStep] = useState(0);

  const chatEndRef = useRef(null);

  // Scroll to bottom on chat update
  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [chat]);

  // Initial greetings
  useEffect(() => {
    if (currentStep === -2) {
      addBotMessage(t.startMessage1);
      setTimeout(() => setCurrentStep(-1), 2000);
    } else if (currentStep === -1) {
      addBotMessage(t.startMessage2);
      setTimeout(() => setCurrentStep(0), 2000);
    } else if (currentStep >= 0 && currentStep < t.questions.length) {
      addBotMessage(t.questions[currentStep]);
    } else if (currentStep === t.questions.length) {
      addBotMessage(t.thankYou);
      setTimeout(() => {
        // Simulate prediction here or fallback risk
        const risk = calculateRisk();
        addBotMessage(t.riskResult(risk));
        setTimeout(() => {
          setCurrentStep(t.questions.length + 1); // ask advice question
          addBotMessage(t.adviceQuestion);
        }, 2000);
      }, 2000);
    }
  // Advice flow
  else if (currentStep === t.questions.length + 1) {
    // Wait for yes/no input for advice
  } else if (currentStep >= t.questions.length + 2) {
    // Advice messages shown
  }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentStep]);

  // Add bot message helper
  function addBotMessage(text) {
    setChat(prev => [...prev, { from: 'bot', text }]);
  }

  // Add user message helper
  function addUserMessage(text) {
    setChat(prev => [...prev, { from: 'user', text }]);
  }

  // Calculate a simple risk based on some inputs (mock)
  function calculateRisk() {
    let risk = 10; // base risk

    if (userAnswers.age && userAnswers.age > 45) risk += 10;
    if (userAnswers.bmi && userAnswers.bmi > 30) risk += 20;
    if (userAnswers.hba1c && userAnswers.hba1c > 6.5) risk += 30;
    if (userAnswers.glucose && userAnswers.glucose > 140) risk += 20;
    if (userAnswers.hypertension.toLowerCase() === t.yes) risk += 10;
    if (userAnswers.heartDisease.toLowerCase() === t.yes) risk += 10;
    if (
      userAnswers.smoking.toLowerCase() === t.yes ||
      userAnswers.smoking.toLowerCase() === (lang === 'en' ? 'current' : lang === 'fr' ? 'actuel' : 'حالي')
    )
      risk += 10;

    if (risk > 100) risk = 100;

    return risk;
  }

  // Handle user input submission
  function handleSubmit(e) {
    e.preventDefault();
    const trimmedInput = input.trim();

    if (!trimmedInput) return;

    addUserMessage(trimmedInput);

    // Process based on currentStep
    if (currentStep >= 0 && currentStep < t.questions.length) {
      // Validate input based on question
      const qIndex = currentStep;
      let valid = false;
      let errMsg = '';

      switch (qIndex) {
        case 0: // age
          const ageNum = Number(trimmedInput);
          if (!isNaN(ageNum) && ageNum >= 1 && ageNum <= 120) {
            setUserAnswers(prev => ({ ...prev, age: ageNum }));
            valid = true;
          } else {
            errMsg = t.enterNumberBetween(1, 120);
          }
          break;
        case 1: // gender
          if (t.genderOptions.some(opt => opt.toLowerCase() === trimmedInput.toLowerCase())) {
            setUserAnswers(prev => ({ ...prev, gender: trimmedInput }));
            valid = true;
          } else {
            errMsg = t.pleaseChoose(t.genderOptions);
          }
          break;
        case 2: // bmi
          const bmiNum = Number(trimmedInput);
          if (!isNaN(bmiNum) && bmiNum >= 10 && bmiNum <= 60) {
            setUserAnswers(prev => ({ ...prev, bmi: bmiNum }));
            valid = true;
          } else {
            errMsg = t.enterNumberBetween(10, 60);
          }
          break;
        case 3: // hba1c
          const hba1cNum = Number(trimmedInput);
          if (!isNaN(hba1cNum) && hba1cNum >= 3 && hba1cNum <= 15) {
            setUserAnswers(prev => ({ ...prev, hba1c: hba1cNum }));
            valid = true;
          } else {
            errMsg = t.enterNumberBetween(3, 15);
          }
          break;
        case 4: // glucose
          const gluNum = Number(trimmedInput);
          if (!isNaN(gluNum) && gluNum >= 50 && gluNum <= 400) {
            setUserAnswers(prev => ({ ...prev, glucose: gluNum }));
            valid = true;
          } else {
            errMsg = t.enterNumberBetween(50, 400);
          }
          break;
        case 5: // hypertension yes/no
          if (
            trimmedInput.toLowerCase() === t.yes.toLowerCase() ||
            trimmedInput.toLowerCase() === t.no.toLowerCase()
          ) {
            setUserAnswers(prev => ({ ...prev, hypertension: trimmedInput.toLowerCase() }));
            valid = true;
          } else {
            errMsg = t.pleaseYesNo;
          }
          break;
        case 6: // heart disease yes/no
          if (
            trimmedInput.toLowerCase() === t.yes.toLowerCase() ||
            trimmedInput.toLowerCase() === t.no.toLowerCase()
          ) {
            setUserAnswers(prev => ({ ...prev, heartDisease: trimmedInput.toLowerCase() }));
            valid = true;
          } else {
            errMsg = t.pleaseYesNo;
          }
          break;
        case 7: // smoking history
          if (t.smokingOptions.some(opt => opt.toLowerCase() === trimmedInput.toLowerCase())) {
            setUserAnswers(prev => ({ ...prev, smoking: trimmedInput.toLowerCase() }));
            valid = true;
          } else {
            errMsg = t.pleaseChoose(t.smokingOptions);
          }
          break;
        default:
          valid = true;
          break;
      }

      if (valid) {
        setInput('');
        setIsTyping(false);
        setCurrentStep(prev => prev + 1);
      } else {
        // Add error bot message
        setInput('');
        addBotMessage(errMsg);
        setIsTyping(false);
      }
    } else if (currentStep === t.questions.length + 1) {
      // Advice yes/no question
      const ans = trimmedInput.toLowerCase();
      if (ans === t.adviceYesNo[0]) {
        setInput('');
        setIsTyping(false);
        setAdviceStep(0);
        setCurrentStep(currentStep + 1);
        addBotMessage(t.generalAdviceTitle);
        addBotMessage(t.generalAdvice[0]);
      } else if (ans === t.adviceYesNo[1]) {
        setInput('');
        setIsTyping(false);
        addBotMessage(t.alrightAdviceDeclined);
        setCurrentStep(currentStep + 2); // End
      } else {
        addBotMessage(t.pleaseYesNo);
        setInput('');
        setIsTyping(false);
      }
    } else if (currentStep > t.questions.length + 1) {
      // Advice steps flow
      // Cycle through general, diet, warning signs advice by adviceStep count
      let nextStep = adviceStep + 1;
      const genLen = t.generalAdvice.length;
      const dietLen = t.dietAdvice.length;
      const warnLen = t.warningSigns.length;

      if (adviceStep < genLen - 1) {
        addBotMessage(t.generalAdvice[nextStep]);
        setAdviceStep(nextStep);
      } else if (adviceStep === genLen - 1) {
        addBotMessage(t.dietAdviceTitle);
        addBotMessage(t.dietAdvice[0]);
        setAdviceStep(genLen);
      } else if (adviceStep >= genLen && adviceStep < genLen + dietLen - 1) {
        addBotMessage(t.dietAdvice[nextStep - genLen]);
        setAdviceStep(nextStep);
      } else if (adviceStep === genLen + dietLen - 1) {
        addBotMessage(t.warningSignsTitle);
        addBotMessage(t.warningSigns[0]);
        setAdviceStep(genLen + dietLen);
      } else if (adviceStep >= genLen + dietLen && adviceStep < genLen + dietLen + warnLen - 1) {
        addBotMessage(t.warningSigns[nextStep - genLen - dietLen]);
        setAdviceStep(nextStep);
      } else if (adviceStep === genLen + dietLen + warnLen - 1) {
        addBotMessage(t.allAdviceDone);
        addBotMessage(t.consultDoctor);
        setAdviceStep(nextStep);
      } else {
        // All advice given, allow user to ask again or end
        if (
          ans === t.adviceYesNo[0]
        ) {
          addBotMessage(t.okayMoreAdvice);
          setAdviceStep(0);
          addBotMessage(t.generalAdviceTitle);
          addBotMessage(t.generalAdvice[0]);
        } else if (
          ans === t.adviceYesNo[1]
        ) {
          addBotMessage(t.alrightAdviceDeclined);
          setCurrentStep(t.questions.length + 3);
        } else {
          addBotMessage(t.pleaseYesNo);
        }
      }
      setInput('');
      setIsTyping(false);
    } else {
      setInput('');
      setIsTyping(false);
    }
  }

  function handleInputChange(e) {
    setInput(e.target.value);
    setIsTyping(true);
  }

  function toggleDarkMode() {
    setDarkMode(prev => !prev);
  }

  function handleLangChange(e) {
    setLang(e.target.value);
    // Reset conversation
    setChat([]);
    setInput('');
    setCurrentStep(-2);
    setUserAnswers({
      age: null,
      gender: '',
      bmi: null,
      hba1c: null,
      glucose: null,
      hypertension: '',
      heartDisease: '',
      smoking: ''
    });
    setAdviceStep(0);
  }

  function handleStartOver() {
    setChat([]);
    setInput('');
    setCurrentStep(-2);
    setUserAnswers({
      age: null,
      gender: '',
      bmi: null,
      hba1c: null,
      glucose: null,
      hypertension: '',
      heartDisease: '',
      smoking: ''
    });
    setAdviceStep(0);
  }

  return (
    <div className={`prediction-container ${darkMode ? 'dark-mode' : 'light-mode'}`} style={{ backgroundImage: `url(${backgroundImage})` }}>
      <div className="header">
        <div className="nav-links">
          <button onClick={() => navigate('/')} className="nav-btn">{t.home}</button>
          <button onClick={() => navigate('/visualization')} className="nav-btn">{t.visualization}</button>
        </div>
        <div className="language-select">
          <label htmlFor="language-select">{t.languageLabel}</label>
          <select id="language-select" value={lang} onChange={handleLangChange}>
            <option value="en">English</option>
            <option value="fr">Français</option>
            <option value="ar">العربية</option>
          </select>
        </div>
        <div className="dark-mode-toggle" onClick={toggleDarkMode} title={darkMode ? t.darkModeOn : t.darkModeOff}>
          <img src={darkMode ? moonIcon : sunIcon} alt="toggle theme" />
        </div>
      </div>

      <div className="chat-window">
        <div className="chat-messages">
          {chat.map((msg, idx) => (
            <div key={idx} className={`chat-message ${msg.from === 'bot' ? 'bot' : 'user'}`}>
              <p>{msg.text}</p>
            </div>
          ))}
          {isTyping && <div className="typing-indicator">{t.typing}</div>}
          <div ref={chatEndRef} />
        </div>

        <form className="chat-input-area" onSubmit={handleSubmit}>
          <input
            type="text"
            value={input}
            onChange={handleInputChange}
            placeholder={
              currentStep >= 0 && currentStep < t.questions.length
                ? t.questions[currentStep]
                : "Type your answer..."
            }
            autoComplete="off"
            autoFocuss
          />
          <button type="submit" disabled={!input.trim()}>
            <img src={sendIcon} alt="Send" />
          </button>
        </form>
      </div>

      <button className="start-over-btn" onClick={handleStartOver}>{t.startOver}</button>
    </div>
  );
};

export default Prediction;
